using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Configure options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// --- 1. Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly ---
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Use it to serialize via the typed overload:
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. Probe without throwing: TryGetTypeInfo ---
// This succeeds because the default resolver can handle any public type.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"TryGetTypeInfo succeeded for Person (runtime type: {info!.Type.Name})");
}

// Now demonstrate a case where resolution is NOT available.
// Use a resolver that only knows about Person — asking for int will fail gracefully.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo(typeof(int), out _))
{
    Console.WriteLine("TryGetTypeInfo found int (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo returned false for int — no exception thrown!");
}

Console.WriteLine("Done.");

// --- Supporting types ---

public record Person(string Name, int Age);

/// A resolver that only provides metadata for <see cref="Person"/>.
file sealed class LimitedResolver : IJsonTypeInfoResolver
{
    private static readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);

        return null; // signal "I don't know this type"
    }
}

